WITH metrics_long AS (SELECT * FROM (SELECT id, device_code, humidity, temp_c FROM device_readings) src UNPIVOT (val FOR metric IN (humidity AS HUMIDITY, temp_c AS TEMP_C_VAL))) SELECT CASE WHEN val >= 68 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, MIN(val) AS min_val, COUNT(DISTINCT id) AS distinct_ids, ROUND(SUM(val) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS val_per_dv_04, COUNT(*) AS row_count, PERCENTILE_APPROX(val, 0.95) AS val_p95 FROM metrics_long GROUP BY 1 HAVING COUNT(DISTINCT id) >= 1 ORDER BY val_tier
